"""Factores temporales explícitos para año2026 normalizado; sin crecimiento ni operación efectiva inventada."""
from pathlib import Path
import argparse, calendar, json, hashlib, math
import pandas as pd
ROOT=Path('etapa2_demanda_anual_20261029/lacustre_temporal')
MAPPING={1:'Verano',2:'Verano',3:'Otoño',4:'Otoño',5:'Otoño',6:'Otoño',7:'Otoño',8:'Otoño',9:'Primavera',10:'Primavera',11:'Primavera',12:'Verano'}
SOURCES=[{'id':'ARISTO107','fuente':'Informe ARISTO.pdf','pagina_impresa':'187–188','tabla':'107','contenido_verificado':'Informe describe flujos totales por sentido y dia; cruce08nov2025 figuraenp188.','uso':'Lectura diaria de exposicion, compatible con multiples filas porfecha.'},{'id':'ARISTO138','fuente':'Informe ARISTO.pdf','pagina_impresa':'207','tabla':'138','contenido_verificado':'Verano:CCaPI01feb2026;PIaCC27ene y01feb2026.','uso':'Fechas de observacion y totalesagregados; no identifica zarpe individual.'},{'id':'ARISTO169','fuente':'Informe ARISTO.pdf','pagina_impresa':'223','tabla':'169','contenido_verificado':'Normal:10mayo2026ambossentidos.','uso':'Fechaobservacion; componentes discrepantes se conservan segunEtapa1.'},{'id':'ARISTO78','fuente':'Informe ARISTO.pdf','pagina_impresa':'173','tabla':'78','contenido_verificado':'Planencuestas08nov2025:CC09y16;PI12y20.','uso':'Dos operaciones planificadas por sentido, no bitacora de zarpes efectivamente realizados.'},{'id':'ARISTO38','fuente':'Informe ARISTO.pdf','pagina_impresa':'111–112','tabla':'38','contenido_verificado':'LaTehuelche:martes1por sentido;domingo2por sentido.','uso':'27ene2026martesPI1;01feb2026domingoPI2,CC2. Programa historico, aplicacion aenerofebrero condicionada.'},{'id':'NAVIERA_MAY2026','fuente':'Itinerario Semanal de Barcazas04–19mayo','url':'https://www.navieraustral.cl/itinerario-semanal-de-barcazas-04-19-mayo/','consulta':'2026-10-29','contenido_verificado':'10may2026:CC16h yPI19h,unzarpeprogramadoporsentido; semana04–10may9tramos/sentido sin clasificar ordinario/especial.','uso':'Denominador programado del10may=1. No certifica realizacion ni cambiafrecuenciaordinaria8confirmadaporusuario.'},{'id':'USUARIO_11_8','fuente':'Confirmacion operacional anterior delusuario en config_matrices_od.json','contenido_verificado':'11zarpesordinarios/sentido/semana dic–abr;8may–nov;no carga peligrosa.','uso':'Escenario programado; no frecuencia efectiva ni total de contingencias.'},{'id':'CAP3_NO_LACUSTRE','fuente':'Cap3inventario local eInformeARISTO§3.2.1–3.2.3','contenido_verificado':'Tráficomensual aereo,PNCterrestre,pasosfronterizos,turismo. Figura9p46 pertenece al traficoAEREO.','uso':'No transferir esos ratios automaticamente aLaTehuelche; invierno/otoño lacustre noidentificado.'}]

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def apply_factors(matrix,factors):
 """Conserva componentes/residuos; no redistribuye ni crea demanda fisica."""
 keys=['campana','sentido_cruce','segmento'];assert not factors.duplicated(keys+['mes','escenario']).any()
 out=matrix.merge(factors,on=keys,how='left',validate='many_to_many');assert not out.mes.isna().any()
 out['flujo_anualizado_mes']=pd.to_numeric(out.flujo,errors='coerce')*out.coef_mes_desde_flujo_fecha
 return out

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--balance',type=Path,default=Path('etapa1_lacustre_aristo_20261029/resultados/entrega_final/csv/balance_por_fecha.csv'));ap.add_argument('--salida',type=Path,default=ROOT/'final');ap.add_argument('--central',choices=['operacional_programado','diario_reportado'],default='operacional_programado');args=ap.parse_args();out=args.salida;out.mkdir(parents=True,exist_ok=True)
 d=pd.read_csv(args.balance,keep_default_na=False,encoding='utf-8-sig');d.F_total_filas_fecha=pd.to_numeric(d.F_total_filas_fecha,errors='coerce');d.filas_medidas=pd.to_numeric(d.filas_medidas,errors='coerce')
 exposure=[]
 for (camp,sense),g in d.groupby(['campana','sentido_cruce'],sort=True):
  # Fechas/fila se cuentan una sola vez, nunca sumando segmentos fisicos.
  unique=g[['fecha','filas_medidas']].drop_duplicates();unique=unique[unique.filas_medidas.notna()];assert unique.fecha.nunique()==len(unique)
  days=len(unique);rows=int(unique.filas_medidas.sum());planned=2 if camp=='Primavera' or camp=='Verano' and sense.startswith('Chile Chico') else 3 if camp=='Verano' else 1
  source='ARISTO78' if camp=='Primavera' else 'ARISTO38+138' if camp=='Verano' else 'NAVIERA_MAY2026+ARISTO169'
  exposure.append(dict(campana=camp,sentido_cruce=sense,fechas_medidas='|'.join(sorted(unique.fecha)),dias_con_medicion=days,filas_conteo=rows,operaciones_programadas_fechas_muestra=planned,operaciones_efectivas_certificadas=False,fuente_denominador_programado=source,advertencia='Plan no certifica bitacora efectiva; una fila no se identifica automaticamente como un zarpe.'))
 e=pd.DataFrame(exposure);e.to_csv(out/'exposicion_por_campana_sentido.csv',index=False,encoding='utf-8-sig')
 sf=d.groupby(['campana','sentido_cruce','segmento','unidad'],dropna=False).F_total_filas_fecha.agg(lambda s:s.sum(min_count=len(s))).reset_index();sf=sf.merge(e,on=['campana','sentido_cruce'],validate='many_to_one')
 common=[]
 for (camp,sense),g in sf.groupby(['campana','sentido_cruce'],sort=True):
  parts=g[g.segmento.isin(['VP'] if camp=='Otoño' else ['VL','MOTO','BICI'])];assert len(parts)==(1 if camp=='Otoño' else 3)
  rr=parts.iloc[0].to_dict();rr['segmento']='PRIVADOS_COMPATIBLES';rr['unidad']='unidades_privadas_heterogeneas_VL_moto_bicicleta';rr['F_total_filas_fecha']=parts.F_total_filas_fecha.sum(min_count=len(parts));common.append(rr)
 sf=pd.concat([sf,pd.DataFrame(common)],ignore_index=True)

 factors=[]
 for r in sf.to_dict('records'):
  for m in range(1,13):
   if MAPPING[m]!=r['campana']:continue
   days=calendar.monthrange(2026,m)[1];freq=11 if m in [1,2,3,4,12] else 8
   daily=days/r['dias_con_medicion'];oper=days*freq/7/r['operaciones_programadas_fechas_muestra'];old=days*freq/7/r['filas_conteo'];central=oper if args.central=='operacional_programado' else daily
   # Baseline conservative equals central until a compatible empirical winter proxy is supplied.
   coeffs={'conservador':central,'central':central,'alto':max(central,old)}
   for scenario,coef in coeffs.items():
    factors.append(dict(campana=r['campana'],sentido_cruce=r['sentido_cruce'],segmento=r['segmento'],unidad=r['unidad'],anio=2026,mes=m,dias_mes=days,escenario=scenario,coef_mes_desde_flujo_fecha=coef,lectura_central=args.central,coef_lectura_total_dia=daily,coef_lectura_operacion_programada=oper,coef_lectura_fila_como_zarpe_07=old,dias_con_medicion=r['dias_con_medicion'],filas_conteo=r['filas_conteo'],operaciones_programadas_muestra=r['operaciones_programadas_fechas_muestra'],frecuencia_programada_semana_por_sentido=freq,factor_crecimiento=1,factor_invierno_sobre_Normal=1,invierno_es_proxy=m in [6,7,8],estatus_invierno='ProxyNormalmayo, NO ratio observado ni limite de incertidumbre' if m in [6,7,8] else 'Perfil estacional transferido',F_exposicion_campana=r['F_total_filas_fecha'],flujo_referencia_mes=r['F_total_filas_fecha']*coef if pd.notna(r['F_total_filas_fecha']) else None,fuente_exposicion=r['fuente_denominador_programado'],calidad='Anualizacion condicional de un año normalizado; no total efectivo observado2026',interpretacion_escenario='Central operativo programado; alto alternativa de2filas=2operacionesVeranoPIvs3planificadas. Conservadorbase=central; proxyinviernoPNCcompatible seaplicaaparteporclase. No intervaloestadistico',agregado_no_sumable_con_componentes=r['segmento']=='PRIVADOS_COMPATIBLES',alcance='Aplicarcoef a cada flujo porfecha deesta campaña y luego sumar; residuos porseparado'))
 f=pd.DataFrame(factors);contrast=f[f.escenario.eq('central')][['campana','sentido_cruce','segmento','unidad','mes','dias_mes','coef_lectura_total_dia','coef_lectura_operacion_programada','coef_lectura_fila_como_zarpe_07']].copy();contrast['estatus']='Contraste de interpretacion, no escenarios centrales ni operacionefectiva';contrast.to_csv(out/'contraste_lectura_diaria_no_central.csv',index=False,encoding='utf-8-sig');assert not f.duplicated(['campana','sentido_cruce','segmento','mes','escenario']).any();f.to_csv(out/'factores_mensuales_lacustres.csv',index=False,encoding='utf-8-sig')
 coverage=f[f.escenario.eq('central')].groupby(['sentido_cruce','segmento','unidad']).agg(meses_con_perfil=('mes',lambda v:'|'.join(str(x) for x in sorted(v.unique()))),numero_meses=('mes','nunique')).reset_index();coverage['cobertura_12meses']=coverage.numero_meses.eq(12);coverage['regla']='Si faltan meses, anual estricto NULL; no rellenar meses ni cambiar VP porVL. PRIVADOS_COMPATIBLES agregado adicional NOsumable concomponentes.';coverage.to_csv(out/'cobertura_anual_unidades.csv',index=False,encoding='utf-8-sig')
 # Quick properties: 12 months,365 days; low<=central<=high for every cell.
 assert sum(calendar.monthrange(2026,m)[1] for m in range(1,13))==365
 pivot=f.pivot(index=['campana','sentido_cruce','segmento','mes'],columns='escenario',values='coef_mes_desde_flujo_fecha');assert (pivot.conservador<=pivot.central).all() and(pivot.central<=pivot.alto).all()
 (out/'fuentes_y_decisiones.json').write_text(json.dumps({'fuentes':SOURCES,'central_propuesta':args.central,'hash_balance_etapa1':sha(args.balance),'regla_12meses':MAPPING,'invierno':'Central1NormalmayoProxy,sincrecimiento. Conservadorbaseigualcentral, agenteprincipalpuedeaplicarproxyPNCempiricoI/Psoloparaclasescompatibles. No se identifico serie propia ferry para calibrar ratio invierno/otoño','limitaciones':['La frecuencia11/8 es ordinaria programada, no operaciones efectivas verificadas.','No se estiman cierres meteorologicos ni desvio contingencias con porcentajes inventados.','El año normalizado no reconstruye cierres, carena o servicio de reemplazo efectivo de2026.','Escenarios conservador/alto no son intervalos estadisticos; conservador pendiente deproxyPNCcompatible porclase, sininventarporcentajes. No cubren toda incertidumbre de composicionOD, geografia, extranjeros o invierno.','La asignacion OtoñoVPagrupado frente VL deotras campañas impide un totalanualVL puro sinhipotesis adicional; integrar vehiculosprivadoscomunes porclase compatible.','Ceros medidos permanecen ceros del estimador no ceros estructurales. NaN nunca se convierte en0.']},ensure_ascii=False,indent=2)+'\n')
 (out/'validacion_temporal.json').write_text(json.dumps({'estado':'correcto','anio':2026,'dias':365,'filas_factores':len(f),'estratos_exposicion':len(e),'sin_crecimiento':bool(f.factor_crecimiento.eq(1).all()),'conservador_menor_central_menor_alto':True,'sin_bitacora_operacion_efectiva':True},ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'estado':'correcto','filas_factores':len(f),'central':args.central},ensure_ascii=False))
if __name__=='__main__':main()
